import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:hive_flutter/hive_flutter.dart';

/// The game's sound effects (generated by `tool/build_sounds.py`).
enum Sound { tap, click, coin, levelup, fanfare, error, ding, whoosh }

/// Plays short sound effects with low latency.
///
/// Sounds respect the device's silent switch and mix with the player's own
/// music. Until [init] finishes (or if audio fails), [play] does nothing, so
/// sound can never break the game.
class Sfx {
  Sfx._();

  static final Sfx instance = Sfx._();

  final Map<Sound, AudioPool> _pools = {};
  final ValueNotifier<bool> muted = ValueNotifier(false);
  Box<dynamic>? _settings;
  DateTime _lastCoin = DateTime.fromMillisecondsSinceEpoch(0);

  static const _maxPlayers = {Sound.coin: 6, Sound.tap: 4, Sound.click: 4};

  Future<void> init() async {
    try {
      _settings = await Hive.openBox<dynamic>('settings');
      muted.value = _settings!.get('muted', defaultValue: false) as bool;

      // iOS "ambient": respects the silent switch and mixes with the
      // player's music. Android: game sounds that never take audio focus.
      final context = AudioContext(
        iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
        android: const AudioContextAndroid(
          contentType: AndroidContentType.sonification,
          usageType: AndroidUsageType.game,
          audioFocus: AndroidAudioFocus.none,
        ),
      );
      await AudioPlayer.global.setAudioContext(context);

      for (final sound in Sound.values) {
        _pools[sound] = await AudioPool.create(
          source: AssetSource('sounds/${sound.name}.wav'),
          maxPlayers: _maxPlayers[sound] ?? 2,
          audioContext: context,
          playerMode: PlayerMode.lowLatency,
        );
      }
    } catch (e) {
      debugPrint('Sound effects disabled: $e');
    }
  }

  void play(Sound sound, {double volume = 1}) {
    if (muted.value) return;
    final pool = _pools[sound];
    if (pool == null) return;
    pool.start(volume: volume).catchError((Object e) async {
      debugPrint('Could not play ${sound.name}: $e');
      return () async {};
    });
  }

  /// A coin landing. Throttled so a burst of coins sounds like a cascade
  /// instead of noise.
  void coin() {
    final now = DateTime.now();
    if (now.difference(_lastCoin) < const Duration(milliseconds: 70)) return;
    _lastCoin = now;
    play(Sound.coin, volume: 0.7);
  }

  void setMuted(bool value) {
    muted.value = value;
    _settings?.put('muted', value);
  }
}
